    ll D=0;
    for(int dx=-mx; dx<=mx; ++dx){
        for(int dy=-my; dy<=my; ++dy){
            if(dx==0 && dy==0) continue;
            ll g = std::gcd(abs(dx), abs(dy));
            if(g<=1) continue;
            ll ways = (ll)(mx+1 - abs(dx)) * (my+1 - abs(dy));
            D += ways * (g-1);
        }
    }
