    ll S_eq = (rawEq - (2*N*N - N))/2;
    ll S_gt = (rawGt - N*(N-1))/2;

    ll A = S_gt - 2*T;
    ll R = S_eq;
    ll O = S_lt - D;

    cout<<A<<"\n"<<R<<"\n"<<O<<"\n"<<D<<"\n";
