array<ll,4> solve(int mx,int my){
    ll N=(ll)(mx+1)*(my+1);
    ll T=N*(N-1)*(N-2)/6;
    ll D=0;
    for(int dx=-mx; dx<=mx; ++dx){
        for(int dy=-my; dy<=my; ++dy){
            if(dx==0 && dy==0) continue;
            ll g = std::gcd(abs(dx), abs(dy));
            if(g<=1) continue;
            ll ways = (ll)(mx+1 - abs(dx)) * (my+1 - abs(dy));
            D += ways * (g-1);
        }
    }
    D/=2;
    int offP = my*my;
    int Pmin=-my*my, Pmax=my*my;
    int sizeP = 2*my*my+1;
    vector<ll> W(sizeP,0);
    for(int c=-my; c<=my; ++c){
        for(int d=-my; d<=my; ++d){
            ll ycnt = cntDiff(my,c,d);
            if(ycnt==0) continue;
            int p=c*d;
            W[p+offP]+=ycnt;
        }
    }
    vector<ll> pref(sizeP+1,0);
    for(int i=0;i<sizeP;i++) pref[i+1]=pref[i]+W[i];
    ll totalY = pref[sizeP];
    auto getPrefLess = [&](ll q)->ll{
        if(q <= Pmin) return 0;
        if(q > Pmax) return totalY;
        return pref[(int)(q+offP)];
    };
    auto getWq = [&](ll q)->ll{
        if(q<Pmin || q>Pmax) return 0;
        return W[(int)(q+offP)];
    };
    ll rawLess=0, rawEq=0, rawGt=0;
    for(int a=-mx; a<=mx; ++a){
        for(int b=-mx; b<=mx; ++b){
            ll xcnt = cntDiff(mx,a,b);
            if(xcnt==0) continue;
            ll q = -(ll)a*b;
            ll less = getPrefLess(q);
            ll eq = getWq(q);
            ll gt = totalY - less - eq;
            rawLess += xcnt*less;
            rawEq += xcnt*eq;
            rawGt += xcnt*gt;
        }
    }
    ll S_lt = rawLess/2;
    ll S_eq = (rawEq - (2*N*N - N))/2;
    ll S_gt = (rawGt - N*(N-1))/2;
    ll A = S_gt - 2*T;
    ll R = S_eq;
    ll O = S_lt - D;
    return {A,R,O,D};
}

array<ll,4> brute(int mx,int my){
    vector<pair<int,int>> pts;
    for(int x=0;x<=mx;x++) for(int y=0;y<=my;y++) pts.push_back({x,y});
    int n=pts.size();
    ll A=0,R=0,O=0,D=0;
    for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)for(int k=j+1;k<n;k++){
        auto [x1,y1]=pts[i]; auto [x2,y2]=pts[j]; auto [x3,y3]=pts[k];
        ll cr=(ll)(x2-x1)*(y3-y1)-(ll)(y2-y1)*(x3-x1);
        if(cr==0){D++;continue;}
        ll d1=(ll)(x2-x1)*(x3-x1)+(ll)(y2-y1)*(y3-y1);
        ll d2=(ll)(x1-x2)*(x3-x2)+(ll)(y1-y2)*(y3-y2);
        ll d3=(ll)(x1-x3)*(x2-x3)+(ll)(y1-y3)*(y2-y3);
        if(d1==0||d2==0||d3==0) R++;
        else if(d1<0||d2<0||d3<0) O++;
        else A++;
    }
    return {A,R,O,D};
}

int main(){
    bool ok=true;
    for(int mx=1;mx<=6;mx++)for(int my=1;my<=6;my++){
        auto s=solve(mx,my); auto b=brute(mx,my);
        if(s!=b){
            ok=false;
            cout<<"Mismatch "<<mx<<" "<<my<<"\n";
            cout<<"solve "<<s[0]<<" "<<s[1]<<" "<<s[2]<<" "<<s[3]<<"\n";
            cout<<"brute "<<b[0]<<" "<<b[1]<<" "<<b[2]<<" "<<b[3]<<"\n";
        }
    }
    if(ok) cout<<"ALL OK\n";
    return 0;
}
